# Phase 2: rate a ticket, low-score email

Class: hot path (tenant scoping; a customer must not touch another organisation's ticket). Spec requirements 1 to 4.

## Context
- `src/portal.js:10-14` `getMyTicket` already answers `null` for another organisation and for a missing ticket; `reply` (line 21) shows the pattern: null for not-found, throw for rule violations.
- `src/notify.js:7` `notifyAgent` throws on a missing agent.
- `src/store.js` has no atomic conditional write. Two simultaneous ratings must not both succeed, so the store gets one method that checks and writes together.

## Files
- Modify `src/store.js` (add `rateTicketOnce` after `updateTicket`), `src/tickets.js` (new fields in `createTicket`, new `rateTicket`, export it), `src/portal.js` (new `rate`, export it), `src/jobs/export-tickets.js` (drop the rating fields from the export).
- Create `test/rating.test.js`. Modify `test/export-tickets.test.js`.

## Steps
- [ ] 1. Failing tests. Create `test/rating.test.js`:
  ```js
  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const { createStore } = require('../src/store');
  const { STATUS, createTicket, assignTicket, resolveTicket } = require('../src/tickets');
  const { drain } = require('../src/notify');
  const portal = require('../src/portal');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);
  const acme = { id: 7, orgId: 1 };
  const globex = { id: 9, orgId: 2 };

  function resolved(store, { owner = 41 } = {}) {
    const t = portal.openTicket(store, acme, { subject: 'Printer', body: 'x' });
    if (owner) assignTicket(store, t.id, owner);
    resolveTicket(store, t.id, 41, { now: at(1) });
    return t.id;
  }

  test('a customer rates a resolved ticket of their organisation', () => {
    const store = createStore();
    const id = resolved(store);
    const r = portal.rate(store, acme, id, 4, { now: at(2) });
    assert.equal(r.csat_score, 4);
    assert.equal(r.csat_rated_at, at(2).toISOString());
    assert.equal(store.getTicket(id).csat_score, 4);
  });

  test('a score that is not a whole number from 1 to 5 is refused', () => {
    const store = createStore();
    const id = resolved(store);
    for (const bad of [0, 6, 3.5, '4', NaN, null, undefined]) {
      assert.throws(() => portal.rate(store, acme, id, bad), /whole number from 1 to 5/);
    }
    assert.equal(store.getTicket(id).csat_score, null);
  });

  test('an open, pending or closed ticket cannot be rated', () => {
    const store = createStore();
    const t = portal.openTicket(store, acme, { subject: 'Printer', body: 'x' });
    assert.throws(() => portal.rate(store, acme, t.id, 4), /cannot rate a open ticket/);
    store.updateTicket(t.id, { status: STATUS.PENDING });
    assert.throws(() => portal.rate(store, acme, t.id, 4), /cannot rate a pending ticket/);
    store.updateTicket(t.id, { status: STATUS.CLOSED });
    assert.throws(() => portal.rate(store, acme, t.id, 4), /cannot rate a closed ticket/);
    assert.equal(store.getTicket(t.id).csat_score, null);
  });

  test('a second rating is refused and the first stays', () => {
    const store = createStore();
    const id = resolved(store);
    portal.rate(store, acme, id, 4, { now: at(2) });
    assert.throws(() => portal.rate(store, acme, id, 1, { now: at(3) }), /already rated/);
    const t = store.getTicket(id);
    assert.equal(t.csat_score, 4);
    assert.equal(t.csat_rated_at, at(2).toISOString());
  });

  test('another organisation gets the same answer as for a missing ticket, and changes nothing', () => {
    const store = createStore();
    const id = resolved(store);
    assert.equal(portal.rate(store, globex, id, 4), null);
    assert.equal(portal.rate(store, globex, 9999, 4), null);
    assert.equal(store.getTicket(id).csat_score, null);
  });

  test('a score of 2 queues one email to the owner; 3 queues none', () => {
    const store = createStore();
    drain();
    portal.rate(store, acme, resolved(store), 2);
    assert.deepEqual(drain().map((m) => [m.to, m.event.type, m.event.score]), [['agent:41', 'low_rating', 2]]);
    portal.rate(store, acme, resolved(store), 3);
    assert.deepEqual(drain(), []);
  });

  test('a low score on an unowned ticket is stored and sends nothing', () => {
    const store = createStore();
    drain();
    const id = resolved(store, { owner: null });
    assert.equal(portal.rate(store, acme, id, 1).csat_score, 1);
    assert.deepEqual(drain(), []);
  });
  ```
  Run `node --test test/rating.test.js`. *Evidence: all seven fail with `portal.rate is not a function`. That proves the file loads and the tests can fail.*
- [ ] 2. Store: in `src/store.js` after `updateTicket` add
