    // Writes the rating only if the ticket is resolved and unrated, in one step. Returns the row, or null.
    // The Postgres store must do this as a single conditional UPDATE.
    rateTicketOnce(id, patch) {
      const t = tickets.get(id);
      if (!t || t.status !== 'resolved' || Number.isInteger(t.csat_score)) return null;
      Object.assign(t, patch);
      return { ...t };
    },
  ```
- [ ] 3. Tickets: add `csat_score: null, csat_rated_at: null,` to the `insertTicket` row in `createTicket` (after `closed_at: null,`). Add before `mustGet`:
  ```js
  // The customer's score for a resolved ticket. One per ticket, ever: a reopened and re-resolved ticket stays rated.
  function rateTicket(store, id, score, { now = new Date() } = {}) {
    if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('the score must be a whole number from 1 to 5');
    const t = mustGet(store, id);
    if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
    if (Number.isInteger(t.csat_score)) throw new Error('this ticket is already rated');
    const updated = store.rateTicketOnce(id, { csat_score: score, csat_rated_at: now.toISOString() });
    if (!updated) throw new Error('this ticket is already rated');
    if (score <= 2 && updated.owner_id) notifyAgent(store, updated.owner_id, { type: 'low_rating', ticketId: id, score });
    return updated;
  }
  ```
  and add `rateTicket` to `module.exports`. (The null from `rateTicketOnce` after the pre-checks means a race lost; the message is the safe one.)
- [ ] 4. Portal: add before `module.exports` in `src/portal.js`
  ```js
