  'use strict';
  const test = require('node:test');
  const assert = require('node:assert/strict');
  const fs = require('node:fs');
  const os = require('node:os');
  const path = require('node:path');
  const { createStore } = require('../src/store');
  const { createTicket, assignTicket, resolveTicket, rateTicket } = require('../src/tickets');
  const { weeklyCsat } = require('../src/jobs/weekly-csat');

  const DAY = 24 * 60 * 60 * 1000;
  const at = (days) => new Date(Date.UTC(2026, 0, 1) + days * DAY);

  function rated(store, owner, score, ratedDay) {
    const t = createTicket(store, { orgId: 1, customerId: 7, subject: 'x', body: 'x', now: at(0) });
    if (owner) assignTicket(store, t.id, owner);
    resolveTicket(store, t.id, 41, { now: at(1) });
    rateTicket(store, t.id, score, { now: at(ratedDay) });
  }

  test('ratings 5, 4 and 1 in the past seven days give three ratings and 3.33; an eight day old one is not counted', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'helpdesk-csat-'));
    try {
      const store = createStore();
      rated(store, 41, 5, 5);
      rated(store, 41, 4, 7);
      rated(store, 41, 1, 9);
      rated(store, 41, 2, 2);      // eight days before the run: not counted
      rated(store, 42, 3, 3);      // exactly seven days before the run: counted
      rated(store, null, 1, 9);    // no owner: nobody to credit
      createTicket(store, { orgId: 1, customerId: 7, subject: 'unrated', body: 'x', now: at(0) });
      const out = weeklyCsat(store, { now: at(10), dir });
      assert.deepEqual(out.rows, [
        { agent_id: 41, ratings: 3, average: 3.33 },
        { agent_id: 42, ratings: 1, average: 3 },
      ]);
      assert.deepEqual(JSON.parse(fs.readFileSync(out.file, 'utf8')), out.rows);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
  ```
  Run `node --test test/weekly-csat.test.js`. *Evidence: fails with `Cannot find module '../src/jobs/weekly-csat'`.*
- [ ] 2. Create `src/jobs/weekly-csat.js`:
  ```js
  'use strict';
  // Nightly. Writes exports/csat-weekly.json: for each agent, how many ratings their tickets received in the past
  // seven days (a rating exactly seven days old counts) and the average score to two decimals. Agents with no
  // ratings are left out; a rated ticket nobody owns is skipped.
  const fs = require('node:fs');
  const path = require('node:path');
  const { EXPORT_DIR } = require('./export-tickets');

  const WINDOW_DAYS = 7;
  const DAY = 24 * 60 * 60 * 1000;

  function weeklyCsat(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const since = now.getTime() - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const t of store.listTickets()) {
      if (!Number.isInteger(t.csat_score) || !t.owner_id) continue;
      if (new Date(t.csat_rated_at).getTime() < since) continue;
      const sums = byAgent.get(t.owner_id) || { ratings: 0, total: 0 };
      sums.ratings += 1;
      sums.total += t.csat_score;
      byAgent.set(t.owner_id, sums);
    }
    const rows = [...byAgent].sort(([a], [b]) => a - b).map(([agent_id, s]) => ({
      agent_id,
      ratings: s.ratings,
      average: Math.round((s.total / s.ratings) * 100) / 100,
    }));
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'csat-weekly.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows };
  }

  module.exports = { weeklyCsat, WINDOW_DAYS };
  ```
